head.b:skin:
/* SUSHI ELITE v70.9 [UX POLISH] */
:root {
    --primary: #ce1212; --primary-dark: #a00d0d;
    --secondary: #37373f; --accent: #ffc107;
    --bg-body: #f8f9fa; --bg-card: #ffffff;
    --text-main: #1d1d1f; --text-muted: #86868b;
    --font-main: "Inter", sans-serif; --font-header: "Amatic SC", sans-serif;
    --radius-xl: 20px;
    --z-marquee: 1040; --z-navbar: 1030; --z-floating: 1035; --z-toast: 1060;
}

[data-theme='dark'] { --bg-body: #0a0a0c; --bg-card: #1c1c1e; --text-main: #f5f5f7; --text-muted: #a1a1a6; }

body { font-family: var(--font-main); background: var(--bg-body); color: var(--text-main); padding-top: 110px; padding-bottom: 90px; overflow-x: hidden; -webkit-tap-highlight-color: transparent; font-size: 0.92rem; }

.marquee-bar { position: fixed; top: 0; left: 0; width: 100%; height: 30px; background: #000; color: #fff; z-index: var(--z-marquee); overflow: hidden; display: flex; align-items: center; font-size: 0.75rem; font-weight: bold; text-transform: uppercase; letter-spacing: 1px; }
.marquee-content { display: inline-block; white-space: nowrap; animation: marquee 20s linear infinite; padding-left: 100%; }
@keyframes marquee { 0% { transform: translate(0, 0); } 100% { transform: translate(-100%, 0); } }

.header { background: var(--bg-card); height: 80px; z-index: var(--z-navbar); border-bottom: 1px solid rgba(0,0,0,0.05); top: 30px; transition: 0.3s; }
.card, .product-card { background: var(--bg-card) !important; border: 1px solid rgba(0,0,0,0.05); }

/* PRODUCT CARD */
.product-card { border-radius: var(--radius-xl); overflow: hidden; height: 100%; transition: 0.3s cubic-bezier(0.165, 0.84, 0.44, 1); position: relative; }
.product-card:hover { transform: translateY(-5px); box-shadow: 0 10px 30px rgba(0,0,0,0.1); }

.product-img-wrapper { position: relative; width: 100%; aspect-ratio: 4 / 3; overflow: hidden; background: #f0f0f0; cursor: pointer; }
.product-img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
.product-card:hover .product-img { transform: scale(1.05); }

/* Wishlist Button (Restored) */
.wish-btn-card { position: absolute; top: 10px; right: 10px; z-index: 10; width: 35px; height: 35px; background: rgba(255,255,255,0.9); backdrop-filter: blur(4px); border-radius: 50%; border: none; display: flex; align-items: center; justify-content: center; color: #ccc; transition: 0.2s; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }
.wish-btn-card.active { color: var(--primary); transform: scale(1.1); }

/* Desktop Hover Action */
.desktop-actions { position: absolute; bottom: 10px; left: 50%; transform: translateX(-50%) translateY(20px); opacity: 0; transition: 0.3s; z-index: 20; width: 90%; text-align: center; }
.product-card:hover .desktop-actions { opacity: 1; transform: translateX(-50%) translateY(0); }
@media (max-width: 991px) { .desktop-actions { display: none; } }

/* Titles - 100% Show */
.product-title { font-weight: 700; line-height: 1.3; font-size: 0.95rem; margin-bottom: 8px; display: block; white-space: normal; }

/* BADGES */
.badge-float { position: absolute; z-index: 10; padding: 4px 10px; border-radius: 4px; font-weight: 800; font-size: 0.65rem; color: #fff; box-shadow: 0 4px 10px rgba(0,0,0,0.2); }
.badge-hot { top: 10px; left: 10px; background: linear-gradient(45deg, #ff0000, #ff8800); }
.badge-stock { top: 10px; right: 10px; background: rgba(0,0,0,0.7); backdrop-filter: none; }
.badge-low { background: #e67e22; animation: pulse 2s infinite; }
.badge-out { background: #c0392b; }
@keyframes pulse { 0% { opacity: 1; } 50% { opacity: 0.6; } 100% { opacity: 1; } }

/* FLOATING CART (Mobile) */
.floating-cart { position: fixed; bottom: 85px; left: 15px; right: 15px; background: var(--text-main); color: #fff; padding: 12px 20px; border-radius: 50px; z-index: var(--z-floating); display: flex; justify-content: space-between; align-items: center; box-shadow: 0 10px 30px rgba(0,0,0,0.25); transform: translateY(150%); transition: 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275); }
.floating-cart.active { transform: translateY(0); }
.floating-cart .price-tag { background: rgba(255,255,255,0.2); padding: 4px 12px; border-radius: 20px; font-weight: 700; margin-left: 10px; }

/* QUICKVIEW PADDING */
.qv-wrapper { padding: 20px; }

/* UI ELEMENTS */
.filter-scroll { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 5px; scrollbar-width: none; }
.filter-scroll::-webkit-scrollbar { display: none; }
.filter-chip { white-space: nowrap; padding: 8px 18px; border-radius: 50px; background: var(--bg-card); border: 1px solid rgba(0,0,0,0.1); color: var(--text-muted); font-weight: 600; cursor: pointer; transition: 0.3s; font-size: 0.85rem; }
.filter-chip:hover, .filter-chip.active { background: var(--primary); color: #fff; border-color: var(--primary); }

.fly-img { position: fixed; z-index: 9999; transition: all 0.8s cubic-bezier(0.19, 1, 0.22, 1); border-radius: 50%; object-fit: cover; pointer-events: none; box-shadow: 0 10px 30px rgba(0,0,0,0.3); }

.toast-container { position: fixed; bottom: 100px; left: 50%; transform: translateX(-50%); z-index: var(--z-toast); width: 90%; max-width: 350px; pointer-events: none; }
.toast { pointer-events: auto; background: var(--bg-card); color: var(--text-main); border: 1px solid rgba(0,0,0,0.1); box-shadow: var(--shadow-lg); border-radius: 12px; margin-bottom: 10px; }

#scroll-sentinel { height: 50px; width: 100%; display: flex; justify-content: center; align-items: center; margin-top: 20px; }
.module-section { display: none !important; opacity: 0; animation: fadeIn 0.4s forwards; }
.module-section.active { display: block !important; opacity: 1; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

.swatch-item { padding: 8px 16px; border-radius: 8px; cursor: pointer; border: 2px solid transparent; background: #eee; font-size: 0.9rem; font-weight: 600; color: #555; transition: 0.2s; margin-right:8px; margin-bottom:8px; display:inline-block; }
.swatch-item.active { border-color: var(--primary); background: var(--primary); color: #fff; }

.delivery-progress { height: 8px; background: #eee; border-radius: 10px; overflow: hidden; margin-top: 5px; }
.delivery-bar { height: 100%; background: var(--primary); width: 0%; transition: width 0.5s; }

.stock-dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; margin-right: 5px; }
.bg-stock-ok { background-color: #198754; }
.bg-stock-low { background-color: #ffc107; }
.bg-stock-out { background-color: #dc3545; }
.variant-select { font-size: 0.85rem; padding: 2px 8px; border-radius: 4px; border: 1px solid #ddd; background: var(--bg-body); color: var(--text-main); cursor: pointer; }

/* MOBILE BOTTOM SHEET MODAL */
@media (max-width: 768px) {
    .modal.fade .modal-dialog { transform: translate(0, 100%); margin: 0; position: fixed; bottom: 0; width: 100%; max-width: 100%; }
    .modal.show .modal-dialog { transform: none; }
    .modal-content { border-radius: 24px 24px 0 0; border: none; min-height: auto; padding-bottom: 20px; }
    .modal-body { overflow-y: auto; max-height: 80vh; }
}

body.script:
//
/**
 * SUSHI ELITE v70.9 [UX PERFECTION]
 */

const CFG = {
    currency: 'DH',
    freeShipThreshold: 150,
    shipCost: 15,
    waNumber: '212600000000',
    mockMenu: [
        {id:'m1', title:'Dragon Roll', cat:'Sushi', price:85, old:100, img:'https://images.unsplash.com/photo-1579584425555-c3ce17fd43fb?w=600', hot:true, stock:50, tags:['hot']},
        {id:'m2', title:'Spicy Tuna', cat:'Sushi', price:60, old:0, img:'https://images.unsplash.com/photo-1611143669185-af224c5e3252?w=600', hot:false, stock:3, tags:[]}
    ]
};

const App = {
    State: {
        catalog: [],
        visibleCount: 0,
        batchSize: 20,
        cart: [], wishlist: [], history: [],
        currency: 'DH',
        activeCat: 'All',
        qvItem: null, qvMult: 1.0, qvQty: 1,
        orderType: 'delivery', 
        tip: 0,
        version: '70.9'
    },

    Utils: {
        safeStr: (str) => str ? str.replace(/['"`]/g, '') : '',
        formatPrice: (val) => val.toFixed(2) + ' ' + App.State.currency,
        checkStock: (item, reqQty = 1) => {
            if(!item) return { label: 'Unknown', class: 'bg-dark', disabled: true };
            if(item.stock === 0) return { label: 'Sold Out', class: 'bg-stock-out text-white', disabled: true };
            if(reqQty > item.stock) return { label: `Only ${item.stock} left`, class: 'bg-stock-low text-dark', disabled: false };
            if(item.stock < 5) return { label: `Low Stock (${item.stock})`, class: 'bg-stock-low text-dark', disabled: false };
            return { label: 'In Stock', class: 'bg-stock-ok text-white', disabled: false };
        },
        getStockBadge: (stock) => {
            if(stock === 0) return { class: 'bg-stock-out', text: 'Out of Stock' };
            if(stock < 5) return { class: 'bg-stock-low', text: `Low Stock (${stock} left)` };
            return { class: 'bg-stock-ok', text: 'In Stock' };
        },
        loadStorage: (key) => {
            try {
                const data = JSON.parse(localStorage.getItem(key));
                return Array.isArray(data) ? data : [];
            } catch(e) { return []; }
        }
    },

    UI: {
        toast: (msg, type='success') => {
            const c = document.getElementById('toast-container');
            if(!c) return;
            const t = document.createElement('div');
            const icon = type==='success' ? 'check-circle' : 'exclamation-circle';
            t.className = `toast p-3 d-flex align-items-center gap-3 border-${type}`;
            t.innerHTML = `<i class="bi bi-${icon} text-${type} fs-4"></i><div class="fw-bold">${msg}</div>`;
            c.appendChild(t);
            setTimeout(() => t.remove(), 3000);
        },
        flip: (imgEl, targetId) => {
            if(!imgEl) return;
            const targetEl = document.getElementById(targetId);
            if(!targetEl) return;
            const clone = imgEl.cloneNode();
            const rect = imgEl.getBoundingClientRect();
            const target = targetEl.getBoundingClientRect();
            clone.className = 'fly-img';
            clone.style.top = `${rect.top}px`;
            clone.style.left = `${rect.left}px`;
            clone.style.width = `${rect.width}px`;
            document.body.appendChild(clone);
            requestAnimationFrame(() => {
                clone.style.top = `${target.top}px`;
                clone.style.left = `${target.left}px`;
                clone.style.width = '20px';
                clone.style.opacity = '0';
            });
            setTimeout(() => clone.remove(), 800);
        }
    },

    Catalog: {
        init: (data) => {
            App.State.catalog = data;
            App.Catalog.renderFilters();
            App.Catalog.initObserver();
            App.Catalog.renderBatch();
            App.Cart.checkUrlShare(); 
        },

        renderFilters: () => {
            const container = document.getElementById('category-filters');
            if(!container) return;
            const cats = ['All', ...new Set(App.State.catalog.map(i => i.cat))];
            container.innerHTML = cats.map(c => 
                `<button class="filter-chip ${c==='All'?'active':''}" onclick="App.Catalog.filter('${c}', this)">${c}</button>`
            ).join('');
        },

        filter: (cat, btn) => {
            App.State.activeCat = cat;
            App.State.visibleCount = 0; 
            const root = document.getElementById('product-grid-root');
            if(root) root.innerHTML = '';
            if(btn) {
                document.querySelectorAll('.filter-chip').forEach(el => el.classList.remove('active'));
                btn.classList.add('active');
            }
            App.Catalog.renderBatch();
            const s = document.getElementById('scroll-sentinel');
            if(s) s.style.display = 'flex';
        },

        renderBatch: () => {
            const { catalog, activeCat, visibleCount, batchSize } = App.State;
            const filtered = activeCat === 'All' ? catalog : catalog.filter(i => i.cat === activeCat);
            const nextBatch = filtered.slice(visibleCount, visibleCount + batchSize);
            const root = document.getElementById('product-grid-root');
            if(!root) return;
            nextBatch.forEach(item => root.appendChild(App.Catalog.createCard(item)));
            App.State.visibleCount += batchSize;
            if(App.State.visibleCount >= filtered.length) {
                const s = document.getElementById('scroll-sentinel');
                if(s) s.style.display = 'none';
            }
        },

        createCard: (item) => {
            const col = document.createElement('div');
            col.className = 'col-lg-4 col-md-6 col-6'; 

            const safeTags = item.tags || [];
            const stock = App.Utils.checkStock(item);
            const badge = item.hot ? '<div class="badge-float badge-hot">HOT</div>' : '';
            const stockBadge = stock.disabled ? `<div class="badge-float badge-stock ${stock.class}">${stock.label}</div>` : '';

            const isWish = App.State.wishlist && App.State.wishlist.some(w => w.id === item.id);
            const heartClass = isWish ? 'active' : '';
            const heartIcon = isWish ? 'bi-heart-fill' : 'bi-heart';

            col.innerHTML = `
            <div class="product-card">
                ${badge} ${stockBadge}
                <div class="product-img-wrapper" id="img-wrap-${item.id}">
                    <button class="wish-btn-card ${heartClass}" onclick="App.Wishlist.toggle('${item.id}', this); event.stopPropagation();">
                        <i class="bi ${heartIcon}"></i>
                    </button>
                    <img src="${item.img}" class="product-img" loading="lazy" onclick="App.QuickView.open('${item.id}')"/>
                    <div class="desktop-actions">
                        <button class="btn btn-light rounded-pill shadow-sm fw-bold px-4" onclick="App.QuickView.open('${item.id}')">
                            <i class="bi bi-eye"></i> Quick View
                        </button>
                    </div>
                </div>
                <div class="p-3">
                    <div class="small text-muted mb-1">${item.cat}</div>
                    <h6 class="product-title">${item.title}</h6>
                    <div class="d-flex justify-content-between align-items-center">
                        <span class="text-primary fw-bold">${App.Utils.formatPrice(item.price)}</span>
                        <button class="btn btn-sm btn-dark rounded-circle" onclick="App.Cart.add('${item.id}', this)" ${stock.disabled?'disabled':''}><i class="bi bi-plus"></i></button>
                    </div>
                </div>
            </div>`;
            return col;
        },

        initObserver: () => {
            const s = document.getElementById('scroll-sentinel');
            if(!s) return;
            const obs = new IntersectionObserver(entries => {
                if(entries[0].isIntersecting) App.Catalog.renderBatch();
            }, { rootMargin: '100px' });
            obs.observe(s);
        }
    },

    Cart: {
        add: (id, btn) => {
            const item = App.State.catalog.find(i => i.id === id);
            if(!item) return;

            const variant = { name: 'Regular', mult: 1.0 };
            const existing = App.State.cart.find(c => c.id === id && c.variant.name === 'Regular');

            if(existing) {
                if(existing.qty + 1 > item.stock) return App.UI.toast('Stock limit reached', 'warning');
                existing.qty++;
            } else {
                if(item.stock < 1) return App.UI.toast('Sold Out', 'danger');
                App.State.cart.push({ ...item, qty: 1, variant: variant });
            }

            App.Cart.save();
            App.Cart.updateBadge();
            if(btn) App.UI.flip(btn.closest('.product-card').querySelector('img'), 'nav-cart-target');
            App.UI.toast('Added to Cart');
        },

        remove: (idx) => { App.State.cart.splice(idx, 1); App.Cart.save(); App.Cart.render(); App.Cart.updateBadge(); },

        updateQty: (idx, delta) => {
            const cItem = App.State.cart[idx];
            const realItem = App.State.catalog.find(i => i.id === cItem.id);
            const newQty = cItem.qty + delta;

            if (newQty < 1) return; 
            if (realItem && newQty > realItem.stock) return App.UI.toast(`Max stock is ${realItem.stock}`, 'warning');

            cItem.qty = newQty;
            App.Cart.save(); App.Cart.render(); App.Cart.updateBadge();
        },

        changeVariant: (idx, el) => {
            const val = el.value.split('|');
            const name = val[0];
            const mult = parseFloat(val[1]);
            App.State.cart[idx].variant = { name, mult };
            App.Cart.save(); App.Cart.render();
        },

        duplicate: (idx) => {
            const item = {...App.State.cart[idx]};
            App.State.cart.splice(idx + 1, 0, item);
            App.Cart.save(); App.Cart.render(); App.Cart.updateBadge();
            App.UI.toast('Item Duplicated');
        },

        share: () => {
            if(App.State.cart.length === 0) return App.UI.toast('Cart is empty', 'warning');
            const simpleCart = App.State.cart.map(i => ({id:i.id, q:i.qty, v:i.variant.name}));
            const str = btoa(JSON.stringify(simpleCart));
            const url = window.location.href.split('?')[0] + '?cart=' + str + '#cart';
            navigator.clipboard.writeText(url).then(() => App.UI.toast('Link Copied to Clipboard!'));
        },

        checkUrlShare: () => {
            const params = new URLSearchParams(window.location.search);
            const shared = params.get('cart');
            if(shared) {
                try {
                    const items = JSON.parse(atob(shared));
                    App.State.cart = []; // Overwrite
                    items.forEach(si => {
                        const catItem = App.State.catalog.find(c => c.id === si.id);
                        if(catItem) {
                            let mult = 1.0;
                            if(si.v === 'Box') mult = 1.2;
                            if(si.v === 'Party') mult = 1.5;
                            App.State.cart.push({...catItem, qty: si.q, variant: {name: si.v, mult: mult}});
                        }
                    });
                    App.Cart.save(); App.Cart.updateBadge();
                    window.location.hash = '#cart';
                    App.UI.toast('Shared Cart Loaded!');
                } catch(e) { console.error('Share Load Error', e); }
            }
        },

        clear: () => { App.State.cart = []; App.Cart.save(); App.Cart.render(); App.Cart.updateBadge(); },
        setType: (type) => { App.State.orderType = type; App.Cart.render(); },
        setTip: (amount) => { App.State.tip = parseInt(amount); App.Cart.render(); },
        applyCoupon: () => { document.getElementById('coupon-feedback').innerText = (document.getElementById('coupon-code').value.toUpperCase() === 'SUSHI10') ? 'Applied!' : 'Invalid'; App.Cart.render(); },
        save: () => localStorage.setItem('se_cart', JSON.stringify(App.State.cart)),
        updateBadge: () => { document.getElementById('nav-cart-count').innerText = App.State.cart.reduce((a,b)=>a+b.qty,0); },

        render: () => {
            const list = document.getElementById('cart-items-list');
            if(!list) return;
            list.innerHTML = '';
            let subtotal = 0;
            let bogoDiscount = 0;
            let dragonRollCount = 0;

            if(App.State.cart.length === 0) list.innerHTML = '<div class="text-center py-5 text-muted">Cart is empty.</div>';
            else {
                App.State.cart.forEach((item, idx) => {
                    const price = item.price * item.variant.mult;
                    const rowTotal = price * item.qty;
                    subtotal += rowTotal;
                    if(item.title.includes('Dragon Roll')) dragonRollCount += item.qty;
                    const liveItem = App.State.catalog.find(c => c.id === item.id);
                    const stockData = App.Utils.getStockBadge(liveItem ? liveItem.stock : 0);

                    list.innerHTML += `
                    <div class="d-flex gap-3 mb-3 border-bottom pb-3">
                        <img src="${item.img}" width="80" height="80" class="rounded object-fit-cover"/>
                        <div class="flex-grow-1">
                            <div class="d-flex justify-content-between mb-1">
                                <div>
                                    <h6 class="m-0 fw-bold">${item.title}</h6>
                                    <small class="text-muted" style="font-size:0.75rem">ID: ${item.id}</small>
                                </div>
                                <span class="fw-bold">${App.Utils.formatPrice(rowTotal)}</span>
                            </div>
                            <div class="d-flex align-items-center gap-2 mb-2">
                                <span class="stock-dot ${stockData.class}"></span>
                                <small class="text-muted" style="font-size:0.75rem">${stockData.text}</small>
                            </div>
                            <div class="d-flex justify-content-between align-items-end">
                                <select class="variant-select" onchange="App.Cart.changeVariant(${idx}, this)">
                                    <option value="Regular|1.0" ${item.variant.name==='Regular'?'selected':''}>Regular</option>
                                    <option value="Box|1.2" ${item.variant.name==='Box'?'selected':''}>Box (1.2x)</option>
                                    <option value="Party|1.5" ${item.variant.name==='Party'?'selected':''}>Party (1.5x)</option>
                                </select>
                                <div class="d-flex align-items-center gap-2">
                                    <button class="btn btn-sm btn-outline-secondary py-0 px-2" onclick="App.Cart.updateQty(${idx}, -1)">-</button>
                                    <span class="fw-bold">${item.qty}</span>
                                    <button class="btn btn-sm btn-outline-secondary py-0 px-2" onclick="App.Cart.updateQty(${idx}, 1)">+</button>
                                    <button class="btn btn-sm border-0 text-muted" onclick="App.Cart.duplicate(${idx})" title="Duplicate"><i class="bi bi-files"></i></button>
                                    <button class="btn btn-sm border-0 text-danger" onclick="App.Cart.remove(${idx})"><i class="bi bi-trash"></i></button>
                                </div>
                            </div>
                        </div>
                    </div>`;
                });
            }

            if (dragonRollCount >= 3) {
                const freeItems = Math.floor(dragonRollCount / 3);
                const dRoll = App.State.cart.find(i => i.title.includes('Dragon Roll'));
                if(dRoll) {
                    bogoDiscount = (dRoll.price * dRoll.variant.mult) * freeItems;
                    document.getElementById('row-bogo').classList.remove('d-none');
                }
            } else document.getElementById('row-bogo').classList.add('d-none');

            const isDel = App.State.orderType === 'delivery';
            let delFee = isDel ? (subtotal >= CFG.freeShipThreshold ? 0 : CFG.shipCost) : 0;

            if(isDel) {
                document.getElementById('delivery-tracker').classList.remove('d-none');
                document.getElementById('field-address').style.display='block';
                document.getElementById('checkout-address').setAttribute('required','true');
                const pct = Math.min((subtotal/CFG.freeShipThreshold)*100, 100);
                document.getElementById('delivery-bar').style.width = pct + '%';
                document.getElementById('delivery-amount').innerText = delFee === 0 ? '' : (CFG.freeShipThreshold - subtotal).toFixed(0) + ' DH Left';
                document.getElementById('type-del').checked = true;
            } else {
                document.getElementById('delivery-tracker').classList.add('d-none');
                document.getElementById('field-address').style.display='none';
                document.getElementById('checkout-address').removeAttribute('required');
                document.getElementById('type-pick').checked = true;
            }

            let couponDisc = document.getElementById('coupon-feedback').innerText === 'Applied!' ? subtotal * 0.10 : 0;
            if(couponDisc > 0) document.getElementById('row-disc').classList.remove('d-none'); else document.getElementById('row-disc').classList.add('d-none');

            const total = subtotal + delFee - couponDisc - bogoDiscount + App.State.tip;

            document.getElementById('sum-sub').innerText = App.Utils.formatPrice(subtotal);
            document.getElementById('sum-del').innerText = isDel && delFee===0 ? 'FREE' : App.Utils.formatPrice(delFee);
            document.getElementById('sum-disc').innerText = '-' + App.Utils.formatPrice(couponDisc);
            document.getElementById('sum-bogo').innerText = '-' + App.Utils.formatPrice(bogoDiscount);
            document.getElementById('sum-total').innerText = App.Utils.formatPrice(total);

            // Update Floating Cart
            const floatCart = document.getElementById('floating-cart');
            const cartCount = App.State.cart.reduce((a,b)=>a+b.qty,0);
            if(cartCount > 0 && window.location.hash !== '#cart') {
                floatCart.classList.add('active');
                document.getElementById('float-count').innerText = cartCount;
                document.getElementById('float-total').innerText = App.Utils.formatPrice(total);
            } else {
                floatCart.classList.remove('active');
            }
        },

        checkout: () => {
            const name = document.getElementById('checkout-name').value;
            const phone = document.getElementById('checkout-phone').value;
            if(!name || !phone) return App.UI.toast('Name & Phone Required', 'danger');

            let msg = `*ORDER ${Date.now().toString().substr(-6)}* %0A`;
            msg += `👤 ${name} (${phone}) %0A`;
            msg += `🚚 ${App.State.orderType.toUpperCase()} ${App.State.orderType==='delivery' ? '@ ' + document.getElementById('checkout-address').value : ''} %0A`;
            msg += `💳 ${document.getElementById('checkout-method').value} %0A`;
            msg += `⏰ ${document.getElementById('order-time').value || 'ASAP'} %0A`;
            if(document.getElementById('order-note').value) msg += `📝 ${document.getElementById('order-note').value} %0A`;
            msg += `--------------------%0A`;
            App.State.cart.forEach(i => msg += `🍱 ${i.qty}x ${i.title} [${i.variant.name}] %0A`);
            msg += `--------------------%0A`;
            msg += `💰 *TOTAL: ${document.getElementById('sum-total').innerText}*`;

            App.State.history.unshift({id:Date.now(), date:new Date().toLocaleDateString(), total:document.getElementById('sum-total').innerText, items:App.State.cart.length, status:'Sent'});
            localStorage.setItem('se_hist', JSON.stringify(App.State.history));
            localStorage.removeItem('se_cart'); App.State.cart = [];
            window.open(`https://wa.me/${CFG.waNumber}?text=${msg}`, '_blank');
            window.location.reload();
        }
    },

    QuickView: {
        open: (id) => {
            const item = App.State.catalog.find(i => i.id === id); if(!item) return;
            App.State.qvItem = item; App.State.qvMult = 1.0; App.State.qvQty = 1;

            const stockInfo = App.Utils.checkStock(item);
            document.getElementById('qv-sku').innerText = `SKU: ${item.id.toUpperCase()}`;

            document.getElementById('quickview-content').innerHTML = `
            <div class="qv-wrapper">
                <div class="text-center mb-3">
                    <img src="${item.img}" class="rounded-4 shadow-sm" style="width:150px; height:150px; object-fit:cover"/>
                </div>
                <h3 class="fw-bold mb-1">${item.title}</h3>
                <div class="d-flex align-items-center gap-2 mb-3">
                    <span class="h4 text-primary fw-bold mb-0" id="qv-price">${App.Utils.formatPrice(item.price)}</span>
                    <span class="badge ${stockInfo.class}">${stockInfo.label}</span>
                </div>

                <div class="mb-4">
                    <label class="small fw-bold text-muted mb-2">SIZE / OPTION</label>
                    <div class="d-flex gap-2">
                        <div class="swatch-item active" onclick="App.QuickView.setOption(1.0, this)">Regular</div>
                        <div class="swatch-item" onclick="App.QuickView.setOption(1.2, this)">Box (1.2x)</div>
                        <div class="swatch-item" onclick="App.QuickView.setOption(1.5, this)">Party (1.5x)</div>
                    </div>
                </div>

                <div class="d-flex justify-content-between align-items-center mb-4 p-3 bg-light rounded-4">
                    <span class="fw-bold">Quantity</span>
                    <div class="d-flex align-items-center gap-3">
                        <button class="qty-btn" onclick="App.QuickView.updateQty(-1)">-</button>
                        <span class="fw-bold fs-5" id="qv-qty">1</span>
                        <button class="qty-btn" onclick="App.QuickView.updateQty(1)" ${stockInfo.disabled?'disabled':''}>+</button>
                    </div>
                </div>

                <div class="d-grid gap-2">
                    <button class="btn btn-primary py-3 rounded-pill fw-bold fs-5" onclick="App.QuickView.add()" ${stockInfo.disabled?'disabled':''}>
                        ADD TO CART
                    </button>
                    <div class="row g-2">
                        <div class="col-6">
                            <button class="btn btn-outline-dark w-100 rounded-pill py-2 fw-bold" onclick="App.QuickView.expressCheckout()">⚡ BUY NOW</button>
                        </div>
                        <div class="col-6">
                            <button class="btn btn-outline-secondary w-100 rounded-pill py-2 fw-bold" onclick="App.QuickView.share()">
                                <i class="bi bi-share"></i> SHARE
                            </button>
                        </div>
                    </div>
                </div>
                <div class="text-center mt-3">
                    <a href="#catalog" class="text-decoration-none small text-muted" onclick="bootstrap.Modal.getInstance(document.getElementById('quickViewModal')).hide()">View Full Details</a>
                </div>
            </div>
            `;
            new bootstrap.Modal(document.getElementById('quickViewModal')).show();
        },

        setOption: (mult, el) => {
            App.State.qvMult = mult;
            document.querySelectorAll('.swatch-item').forEach(e => e.classList.remove('active'));
            el.classList.add('active');
            document.getElementById('qv-price').innerText = App.Utils.formatPrice(App.State.qvItem.price * mult);
        },

        updateQty: (delta) => {
            const newQ = App.State.qvQty + delta;
            if(newQ < 1) return;
            if(newQ > App.State.qvItem.stock) return App.UI.toast(`Max stock is ${App.State.qvItem.stock}`);
            App.State.qvQty = newQ;
            document.getElementById('qv-qty').innerText = newQ;
        },

        add: () => {
            const item = App.State.qvItem;
            const variantName = App.State.qvMult === 1.2 ? 'Box' : (App.State.qvMult === 1.5 ? 'Party' : 'Regular');
            // Loop to add multiple
            const existing = App.State.cart.find(c => c.id === item.id && c.variant.name === variantName);
            if(existing) {
                existing.qty += App.State.qvQty;
            } else {
                App.State.cart.push({...item, qty: App.State.qvQty, variant: {name:variantName, mult:App.State.qvMult}});
            }

            App.Cart.save(); App.Cart.updateBadge(); App.Cart.render();
            bootstrap.Modal.getInstance(document.getElementById('quickViewModal')).hide();
            App.UI.toast('Added to Cart');
        },

        expressCheckout: () => {
            const item = App.State.qvItem;
            const total = (item.price * App.State.qvMult * App.State.qvQty).toFixed(2);
            const msg = `*EXPRESS ORDER* %0A📦 ${item.title} x${App.State.qvQty} (${total} DH)`;
            window.open(`https://wa.me/${CFG.waNumber}?text=${msg}`, '_blank');
        },

        share: () => {
            const url = window.location.href.split('#')[0] + '#product/' + App.State.qvItem.id;
            navigator.clipboard.writeText(url).then(() => App.UI.toast('Link Copied!'));
        }
    },

    Wishlist: {
        toggle: (id, btn) => {
            const idx = App.State.wishlist.findIndex(w => w.id === id);
            if(idx > -1) { 
                App.State.wishlist.splice(idx, 1); 
                if(btn) { btn.innerHTML='<i class="bi bi-heart"></i>'; btn.classList.remove('active'); }
            } 
            else { 
                const i = App.State.catalog.find(x => x.id === id); 
                if(i) { 
                    App.State.wishlist.push(i); 
                    if(btn) { btn.innerHTML='<i class="bi bi-heart-fill text-danger"></i>'; btn.classList.add('active'); }
                } 
            }
            localStorage.setItem('se_wish', JSON.stringify(App.State.wishlist)); 
            document.getElementById('nav-wish-count').innerText = App.State.wishlist.length;
            if(window.location.hash === '#wishlist') App.Wishlist.render();
        },
        clear: () => { App.State.wishlist = []; localStorage.setItem('se_wish', '[]'); App.Wishlist.render(); },
        render: () => { const r = document.getElementById('wishlist-grid-root'); r.innerHTML=''; App.State.wishlist.forEach(i => r.appendChild(App.Catalog.createCard(i))); }
    },

    Seo: { injectSchema: (i) => { const s = document.createElement('script'); s.type='application/ld+json'; s.text = JSON.stringify({"@context":"https://schema.org/","@type":"Product","name":i.title,"image":i.img,"offers":{"@type":"Offer","price":i.price,"priceCurrency":"MAD"}}); document.head.appendChild(s); } },

    Router: () => {
        const hash = window.location.hash || '#home';
        document.querySelectorAll('.module-section').forEach(e => e.classList.remove('active'));
        const t = document.querySelector(hash + '-module'); if(t) t.classList.add('active');

        // Hide floating cart on cart page
        if(hash === '#cart') document.getElementById('floating-cart').classList.remove('active');
        else App.Cart.render(); // Update floating cart visibility

        if(hash === '#wishlist') App.Wishlist.render();
        window.scrollTo(0,0);
    }
};

const API = {
    parse: (json) => {
        if(!json.feed.entry) return API.fallback();
        App.State.catalog = json.feed.entry.map(e => {
            const tags = e.category ? e.category.map(c=>c.term) : [];
            let p=50, s=20, a=null;
            tags.forEach(t=>{ if(t.startsWith('price-')) p=parseFloat(t.split('-')[1]); if(t.startsWith('stock-')) s=parseInt(t.split('-')[1]); if(t.startsWith('img-alt-url-')) a=t.replace('img-alt-url-','https://'); });
            return { id: e.id.$t.split('-').pop(), title: e.title.$t, img: e.media$thumbnail?e.media$thumbnail.url.replace('s72-c','w600-h600-c'):'', price:p, stock:s, cat:'General', hot:tags.includes('hot'), tags:tags };
        });
        App.Catalog.init(App.State.catalog);
    },
    fallback: () => App.Catalog.init(CFG.mockMenu)
};

document.addEventListener('DOMContentLoaded', () => {
    if(localStorage.getItem('se_version') !== App.State.version) { localStorage.removeItem('se_cart'); localStorage.setItem('se_version', App.State.version); App.State.cart=[]; }
    else App.State.cart = App.Utils.loadStorage('se_cart');
    App.State.wishlist = App.Utils.loadStorage('se_wish');

    const s = document.createElement('script'); s.src = 'https://eventsushi.blogspot.com/feeds/posts/default?alt=json-in-script&callback=API.parse&max-results=500'; s.onerror=API.fallback; document.body.appendChild(s);
    AOS.init();
    if(document.getElementById('order-time')) flatpickr('#order-time', { enableTime: true, dateFormat: "Y-m-d H:i" });
    App.Router(); window.addEventListener('hashchange', App.Router); App.Cart.updateBadge();
});
